INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q43','nism-5a-z20','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹3,75,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹75,000","₹31,250","₹46,875","₹50,000"]',1,'Taxable = 375000 − 1,25,000; tax at 12.5% = ₹31,250.',43) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q44','nism-5a-z20','An investor holds 405 units under the IDCW Reinvestment option. IDCW is ₹1.5 per unit and the ex-IDCW NAV is ₹25. The additional units allotted are:','["22.92","607.50","48.60","24.30"]',3,'Units = (405 × 1.5) ÷ 25 = 24.30.',44) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q45','nism-5a-z20','An NAV rising from ₹12 to ₹15 gives a simple return of:','["20%","25%","30%","15%"]',1,'(15 − 12) ÷ 12 = 25%.',45) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q46','nism-5a-z20','The record date for IDCW is how many days from the notice?','["5 calendar days","10 working days","30 days","1 day"]',0,'Public notice within 1 day of the trustee decision.',46) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q47','nism-5a-z20','Index funds and ETFs offer:','["Market return with no selection risk and lower cost","Higher cost than active funds","Protection when the index falls","Guaranteed returns"]',0,'Their NAV still falls when the index falls.',47) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q48','nism-5a-z20','In the SEBI CAGR method with IDCW, the IDCW is assumed to be:','["Reinvested at face value","Paid out and ignored","Reinvested at the next day''s NAV","Reinvested at the ex-IDCW NAV"]',3,'This increases the number of units.',48) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q49','nism-5a-z20','The minimum period an NFO must remain open and the maximum (other than ELSS) are:','["7 days and 60 days","1 day and 7 days","5 days and 30 days","3 working days and 15 days"]',3,'Allotment/refund within 5 business days of closing.',49) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q50','nism-5a-z20','A portfolio of ₹13,00,000 is 50:50 equity:debt. Equity rises 20% and debt is unchanged. To rebalance to the original ratio, the amount of equity to be sold is:','["₹65,000","₹2,60,000","₹97,500","₹1,30,000"]',0,'New equity = 780000; target = 715000; sell the excess.',50) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q51','nism-5a-z20','Debt-oriented mutual fund gains are taxed at:','["Nil","Slab rates for both short-term and long-term","20% STCG only","12.5% LTCG"]',1,'Per the Sept 2026 workbook.',51) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q52','nism-5a-z20','With a scheme return of 7%, risk-free 5% and standard deviation 0.5%, the Sharpe ratio is:','["2","4","14","0.25"]',1,'(7 − 5) ÷ 0.5 = 4.',52) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q53','nism-5a-z20','The Price Return Index captures:','["Price changes plus reinvested dividends","Price changes only","Dividends only","Interest only"]',1,'This gave schemes an unfair advantage over PRI.',53) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q54','nism-5a-z20','The standard additional benchmark for equity schemes is:','["10-year GoI security","Sensex or Nifty","1-year T-bill","Gold price"]',1,'Debt ≤1 year and Arbitrage: 1-year T-bill; others: 10-year GoI.',54) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q55','nism-5a-z20','Tracking error is the standard deviation of:','["NAV","Excess returns over the benchmark","Expenses","Dividends"]',1,'For an index fund it should ideally be zero.',55) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z20-q56','nism-5a-z20','An STP involves:','["Switching to another AMC","A transfer of folio","An SWP from a source scheme and an SIP into a target scheme of the same MF","A lump sum into two schemes"]',2,'It avoids idle money and double paperwork.',56) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
